```js
const handlers = [];
function ControllerAdvice(fn){ handlers.push(fn); }
function handle(err){
  for (const h of handlers){ const r = h(err); if (r) return r; }
  return { code: 500, message: "系统错误", data: null };
}
class BizException extends Error { constructor(code, message){ super(message); this.code=code; this.biz=true; } }
ControllerAdvice(e => { if (e.biz) return { code: e.code, message: e.message, data: null }; });
ControllerAdvice(e => { if (e instanceof Error) return { code: 500, message: "系统繁忙", data: null }; });
console.log(JSON.stringify(handle(new BizException(1001, "用户不存在"))));
```

下面的全局异常处理，把系统异常的堆栈直接序列化进了响应体。改正它。

```java
@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(Exception.class)
    public ApiError handleOther(Exception e) {
        return new ApiError(5000, e.toString(), e.getStackTrace()); // 泄露堆栈
    }
}
```

