@RestControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(Exception.class)
    public ApiError handleOther(Exception e) {
        log.error("unexpected error", e);            // 堆栈落服务端日志
        return new ApiError(5000, "系统繁忙，请稍后再试", null); // 前端只见中性提示
    }
}

function validateLogin(dto){
  if(!dto.username) return 'username 必填';
  if(!/^\w{3,}$/.test(dto.username)) return 'username 至少3位';
  if(!dto.password) return 'password 必填';
  return null;
}
function loginService(dto){
  if(dto.username==='admin' && dto.password==='123456') return { token: 'tk_abc' };
  throw new Error('用户名或密码错误');
}
function controller(dto){
  const verr = validateLogin(dto);
  if(verr) return { code:400, message:verr, data:null };
  try { const data = loginService(dto); return { code:0, message:'ok', data }; }
  catch(e){ return { code:500, message:'系统繁忙', data:null }; } // 不暴露 e
}
console.log(JSON.stringify(controller({username:'ad',password:'123456'})));
console.log(JSON.stringify(controller({username:'admin',password:'wrong'})));
console.log(JSON.stringify(controller({username:'admin',password:'123456'})));

